queries.query:
find view "view:pipeline:pipeline_execution" pe
| filter pe.start_ts >= cast(${start_time} as timestamp) and pe.start_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { count() as executions }

find view "view:pipeline:pipeline_execution" pe
| filter pe.start_ts >= cast(${start_time} as timestamp) and pe.start_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { distinct_count(pe.project_identifier) as projects }

find view "view:pipeline:pipeline_execution" pe
| filter pe.start_ts >= cast(${start_time} as timestamp) and pe.start_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { distinct_count(pe.pipeline_identifier) as pipelines }

find view "view:pipeline:stage_execution" s
| filter s.start_ts >= cast(${start_time} as timestamp) and s.start_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { (case when s.stage_type = 'CI' then 'CI' when s.stage_type = 'Deployment' or s.stage_type = 'Custom' then 'CD' when s.stage_type = 'IACM' then 'IaCM' when s.stage_type = 'IDP' then 'IDP' else 'Platform' end) as module, distinct_count(s.plan_execution_id) as executions }
| group_by module
| order_by executions desc

find view "view:pipeline:stage_execution" s
| filter s.start_ts >= cast(${start_time} as timestamp) and s.start_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { date_trunc("month", s.start_ts) as month, (case when s.stage_type = 'CI' then 'CI' when s.stage_type = 'Deployment' or s.stage_type = 'Custom' then 'CD' when s.stage_type = 'IACM' then 'IaCM' when s.stage_type = 'IDP' then 'IDP' else 'Platform' end) as module, distinct_count(s.plan_execution_id) as executions }
| group_by month, module
| order_by month asc

find view "ci:pipeline_execution_summary_ci" pe
| filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { count() as builds }

find view "ci:pipeline_execution_summary_ci" pe
| filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { count(case when pe.status = 'SUCCESS' or pe.status = 'IGNOREFAILED' then 1 end) * 100.0 / count() as success_rate }

find view "ci:pipeline_execution_summary_ci" pe
| filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate} and pe.build_duration > 0
| aggregate { median(pe.build_duration) / 1000.0 as median_build_seconds }

find view "cd:deployment_stage_execution" d
| filter d.end_ts >= cast(${start_time} as timestamp) and d.end_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate} and ${env_type_filter_predicate}
| aggregate { count() as deployments }

find view "cd:deployment_stage_execution" d
| filter d.end_ts >= cast(${start_time} as timestamp) and d.end_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate} and ${env_type_filter_predicate} and d.service_identifier is not null and d.service_identifier is not empty
| aggregate { distinct_count(d.service_identifier) as services_deployed }

find view "cd:deployment_stage_execution" d
| filter d.end_ts >= cast(${start_time} as timestamp) and d.end_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate} and ${env_type_filter_predicate}
| aggregate { count() * 7.0 / date_diff(cast(${start_time} as timestamp), cast(${end_time} as timestamp), "day") as per_week }

find view "cd:deployment_stage_execution" d
| filter d.end_ts >= cast(${start_time} as timestamp) and d.end_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate} and ${env_type_filter_predicate} and d.stage_duration > 0
| aggregate { median(d.stage_duration) / 1000.0 as median_seconds }

find view "cd:deployment_stage_execution" d
| filter d.end_ts >= cast(${start_time} as timestamp) and d.end_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate} and ${env_type_filter_predicate}
| aggregate { count(case when d.stage_status = 'FAILED' or d.stage_status = 'ABORTED' or d.stage_status = 'EXPIRED' or d.stage_status = 'APPROVAL_REJECTED' then 1 end) * 100.0 / count() as change_failure_rate }

find view "view:sto:scan" s
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = s.parent_unique_id and h_l.account_identifier = s.account_identifier
| filter s.created >= cast(${start_time} as timestamp) and s.created <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { count() as scans }

find view "view:sto:all_baseline_issue_summary" a
| inner join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = a.parent_unique_id and h_l.account_identifier = a.account_identifier
| filter a.status = 'Active' and a.last_modified >= cast(${start_time} as timestamp) and a.last_modified <= cast(${end_time} as timestamp)
    and (a.severity_code = 'Critical' or a.severity_code = 'High') and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { distinct_count(a.issue_id) as critical_high_issues }

find view "view:sto:scan" s
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = s.parent_unique_id and h_l.account_identifier = s.account_identifier
| filter s.created >= cast(${start_time} as timestamp) and s.created <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { distinct_count(s.target_variant_id) as targets }

find view "view:pipeline:pipeline_execution" pe
| left join view "view:sto:scan" s on s.plan_execution_id = pe.plan_execution_id
| filter pe.start_ts >= cast(${start_time} as timestamp) and pe.start_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { distinct_count(s.pipeline_identifier) * 100.0 / distinct_count(pe.pipeline_identifier) as scan_coverage }

find view "view:sto:detection" det
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = det.parent_unique_id and h_l.account_identifier = det.account_identifier
| filter det.detected >= cast(${start_time} as timestamp) and det.detected <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { date_trunc("week", det.detected) as week, det.severity_code as severity, count() as issues_detected }
| group_by week, severity
| order_by week asc

find view "view:pipeline:pipeline_execution" pe
| left join view "ci:pipeline_execution_summary_ci" ci on ci.planexecutionid = pe.plan_execution_id
| left join view "cd:deployment_stage_execution" d on d.plan_execution_id = pe.plan_execution_id
| left join view "view:sto:scan" s on s.plan_execution_id = pe.plan_execution_id
| filter pe.start_ts >= cast(${start_time} as timestamp) and pe.start_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { cast(round(distinct_count(d.stage_execution_id) * 2.0 + distinct_count(ci.planexecutionid) * 0.25, 0) as double) as hours_automated }

find view "view:pipeline:pipeline_execution" pe
| left join view "ci:pipeline_execution_summary_ci" ci on ci.planexecutionid = pe.plan_execution_id
| left join view "cd:deployment_stage_execution" d on d.plan_execution_id = pe.plan_execution_id
| left join view "view:sto:scan" s on s.plan_execution_id = pe.plan_execution_id
| filter pe.start_ts >= cast(${start_time} as timestamp) and pe.start_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { cast(round((distinct_count(d.stage_execution_id) * 2.0 + distinct_count(ci.planexecutionid) * 0.25 + distinct_count(s.id) * 0.5) * 100, 0) as double) as estimated_savings_usd }

find view "view:pipeline:pipeline_execution" pe
| left join view "ci:pipeline_execution_summary_ci" ci on ci.planexecutionid = pe.plan_execution_id
| left join view "cd:deployment_stage_execution" d on d.plan_execution_id = pe.plan_execution_id
| left join view "view:sto:scan" s on s.plan_execution_id = pe.plan_execution_id
| filter pe.start_ts >= cast(${start_time} as timestamp) and pe.start_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { cast(round(distinct_count(s.id) * 0.5, 1) as double) as security_hours_saved }

find view "cd:deployment_stage_execution" d
| filter d.end_ts >= cast(${start_time} as timestamp) and d.end_ts <= cast(${end_time} as timestamp) and ${org_filter_predicate} and ${project_filter_predicate} and ${env_type_filter_predicate}
| aggregate { count(case when d.env_type != 'Production' and (d.stage_status = 'FAILED' or d.stage_status = 'ABORTED' or d.stage_status = 'EXPIRED' or d.stage_status = 'APPROVAL_REJECTED') then 1 end) as caught_before_prod }
